import csv, openpyxl
from pathlib import Path

ws_dir = Path("scan")
posts = list(csv.DictReader(open(ws_dir / "posts.csv", encoding="utf-8")))

wb = openpyxl.load_workbook(ws_dir / "capture.xlsx")
ws = wb["Ads"]
hdr = [c.value for c in ws[1]]
missing = []
row_i = 2
for p in posts:
    sc = p["shortcode"]
    if sc not in C:
        missing.append(sc)
        continue
    (pf, ag, ct, c1, c2, reg, pd_, wf, pv, eco, camp, obj, lang, note) = C[sc]
    d = {"post_id": sc, "brand": p["brand"], "ring": p["ring"], "handle": p["handle"],
         "date": "", "format": "video" if p["kind"] == "reel" else "static",
         "product_focus": pf, "audience_generation": ag, "content_type": ct,
         "claim_primary": c1, "claim_secondary": c2, "register": reg,
         "proof_device": pd_, "who_is_in_frame": wf, "production_value": pv,
         "ecosystem_push": eco, "campaign_platform": camp, "addresses_objection": obj,
         "language_lead": lang, "reposted_from": p["reposted_from"],
         "source_url": p["source_url"], "image_file": p["image_file"],
         "coder": "claude", "notes": note}
    for j, col in enumerate(hdr, start=1):
        ws.cell(row=row_i, column=j, value=d.get(col, ""))
    row_i += 1
wb.save(ws_dir / "capture.xlsx")
print(f"coded {row_i-2} rows; uncoded shortcodes: {missing}")
